def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")
    words = text.split()
    if not words:
        return []
    result = []
    current_line = ""
    def place(token):
        nonlocal current_line
        if current_line == "":
            current_line = token
        else:
            if len(current_line) + 1 + len(token) <= width:
                current_line += " " + token
            else:
                result.append(current_line)
                current_line = token
    i = 0
    while i < len(words):
        word = words[i]
        i += 1
        if len(word) > width:
            # split into chunks of exactly width
            chunks = [word[j:j+width] for j in range(0, len(word), width)]
            for chunk in chunks:
                place(chunk)
        else:
            place(word)
    if current_line != "":
        result.append(current_line)
    return result

# Test cases
tests = [
    # Example 1
    ("the quick brown fox", 10, ["the quick", "brown fox"]),
    # Example 2
    ("abcdefghij", 4, ["abcd", "efgh", "ij"]),
    # Example 3
    ("", 5, []),
    # Example 4: should raise ValueError
    ("a b", 0, "error"),
    # Additional test: simple split
    ("a b", 1, ["a", "b"]),
    # Additional test: width equals word length
    ("hello world", 5, ["hello", "world"]),
    # Additional test: mixed words
    ("this is a test", 7, ["this is", "a test"]),
    # Additional test: long word splitting
    ("supercalifragilisticexpialidocious", 5, ["super", "calif", "ragil", "istic", "expre", "ssion"]),
]

all_passed = True
for idx, (txt, w, expected) in enumerate(tests):
    try:
        result = wrap(txt, w)
        if expected == "error":
            # Expect ValueError
            raise AssertionError("Expected ValueError but got result")
        if result != expected:
            print(f"Test {idx} FAILED: wrap({txt!r}, {w}) returned {result}, expected {expected}")
            all_passed = False
        else:
            print(f"Test {idx} PASSED")
    except ValueError as e:
        if expected == "error":
            print(f"Test {idx} PASSED (raised ValueError as expected)")
        else:
            print(f"Test {idx} FAILED: Unexpected ValueError raised")
            all_passed = False
    except Exception as e:
        print(f"Test {idx} FAILED: Unexpected exception {e}")
        all_passed = False

if all_passed:
    print("ALL TESTS PASSED")

